style.css:
@-moz-document url-prefix("https://voice.google.com/") {
#gv-root {
    background-color: #222 !important;
    color: #FFF;
}

#gv-root div {
    --mat-sys-background: #111;
    border-color: #000 !important;
    border-width: 1px;
}

#gb,
#gb div,
gv-thread-details,
header,
mat-card,
.content-container gv-side-nav,
.list-item:hover,
.mat-mdc-card,
.message-entry-container,
.messaging-view,
.sZ3gbf,
.thread-detail-container,
.threads {
    background-color: #222 !important;
}

.upgrade-link {
    display: none;
}

.learn-more-button {
    margin-left: 10px;
}

.mat-divider {
    background-color: #222 !important;
    color: #222 !important;
    border-top-style: solid;
    border-top-color: #222;
    border-top-width: 1px;
}

.button-container button,
.cdk-visually-hidden,
.header-content h2,
.header-title,
.internalHeader,
.label,
.mat-icon,
.mdc-button__label div,
.name,
.participant,
.participants,
.phone-number-details span,
.primary-text,
.subtitle,
.threads-button div,
.time-container div,
.title,
.transcription-text {
    color: #DDD !important;
}

.buttonContent span,
.caption,
.device-details,
.deviceDetails,
.mat-mdc-list-item-icon,
.nav-item-label,
.navItemLabel,
.phone-number,
.preview,
.secondary-text,
.sectionTitle,
.status,
.timestamp {
    color: #AAA !important;
}

.deviceLabel,
.greeting {
    color: #FFF !important;
}

.no-devices {
    color: #FFF !important;
    font-weight: bold;
}

.internalSubheader,
.subheader {
    color: #777 !important;
}

mat-drawer-content div.header,
.calling-view,
.help-panel-header,
.inbox-summary-container,
.threads-header {
    background-color: #111 !important;
}

gv-call-sidebar {
    background-color: #222 !important;
}

.action-buttons,
.block-container,
.mat-drawer-content div.header,
.mat-mdc-button-persistent-ripple,
.mat-mdc-button-ripple {
    background-color: #333 !important;
}

gv-call-as-banner,
.active,
.dialpad-container,
.gv-clickable-list-item,
.input-row,
.mat-mdc-dialog-surface .full-panel {
    background-color: #444 !important;
}

.mdc-button {
    background-color: #FFF;
}

.mat-mdc-text-field-wrapper {
    background-color: #BBB !important
}

.list-item:hover {
    background-color: black;
}

gv-mei-banner div,
.input,
.outgoing div.bubble {
    background-color: #111 !important;
    color: #777;
}

div.bubble {
    background-color: #444 !important;
    color: #AAA !important;
}

.header {
    background-color: #333 !important;
    color: #CCC !important;
}

.mdc-list-item--activated {
    background-color: #333 !important;
    color: #FFF !important;
}

#contact-list,
.contacts,
.gb_Me div,
.message-input-container textarea,
.root .container {
    background-color: #222 !important;
    color: #BBB !important;
}

.gb_Pd,
.input-and-actions-row textarea {
    background-color: #F9F9F9 !important;
    color: black !important;
}
}
